<?php
 namespace QQWorld\Customer\Model; use QQWorld\Framework\App\Config\ScopeConfigInterface; use QQWorld\Framework\DataObject; use QQWorld\Framework\Exception\LocalizedException; use QQWorld\Store\Model\Store; use QQWorld\Store\Model\Information as StoreInformation; use Psr\Log\LoggerInterface as PsrLogger; use QQWorld\Store\Model\ScopeInterface; class Vat { const XML_PATH_CUSTOMER_VIV_INTRA_UNION_GROUP = 'customer/create_account/viv_intra_union_group'; const XML_PATH_CUSTOMER_VIV_DOMESTIC_GROUP = 'customer/create_account/viv_domestic_group'; const XML_PATH_CUSTOMER_VIV_INVALID_GROUP = 'customer/create_account/viv_invalid_group'; const XML_PATH_CUSTOMER_VIV_ERROR_GROUP = 'customer/create_account/viv_error_group'; const VAT_CLASS_DOMESTIC = 'domestic'; const VAT_CLASS_INTRA_UNION = 'intra_union'; const VAT_CLASS_INVALID = 'invalid'; const VAT_CLASS_ERROR = 'error'; const VAT_VALIDATION_WSDL_URL = 'http://ec.europa.eu/taxation_customs/vies/services/checkVatService?wsdl'; const XML_PATH_CUSTOMER_GROUP_AUTO_ASSIGN = 'customer/create_account/auto_group_assign'; const XML_PATH_EU_COUNTRIES_LIST = 'general/country/eu_countries'; protected $scopeConfig; protected $logger; public function __construct( ScopeConfigInterface $scopeConfig, PsrLogger $logger ) { $this->scopeConfig = $scopeConfig; $this->logger = $logger; } public function getMerchantCountryCode($store = null) { return (string)$this->scopeConfig->getValue( StoreInformation::XML_PATH_STORE_INFO_COUNTRY_CODE, ScopeInterface::SCOPE_STORE, $store ); } public function getMerchantVatNumber($store = null) { return (string)$this->scopeConfig->getValue( StoreInformation::XML_PATH_STORE_INFO_VAT_NUMBER, ScopeInterface::SCOPE_STORE, $store ); } public function getCustomerGroupIdBasedOnVatNumber($customerCountryCode, $vatValidationResult, $store = null) { $groupId = null; $isAutoGroupAssign = $this->scopeConfig->isSetFlag( self::XML_PATH_CUSTOMER_GROUP_AUTO_ASSIGN, ScopeInterface::SCOPE_STORE, $store ); if (!$isAutoGroupAssign) { return $groupId; } $vatClass = $this->getCustomerVatClass($customerCountryCode, $vatValidationResult, $store); $vatClassToGroupXmlPathMap = [ self::VAT_CLASS_DOMESTIC => self::XML_PATH_CUSTOMER_VIV_DOMESTIC_GROUP, self::VAT_CLASS_INTRA_UNION => self::XML_PATH_CUSTOMER_VIV_INTRA_UNION_GROUP, self::VAT_CLASS_INVALID => self::XML_PATH_CUSTOMER_VIV_INVALID_GROUP, self::VAT_CLASS_ERROR => self::XML_PATH_CUSTOMER_VIV_ERROR_GROUP, ]; if (isset($vatClassToGroupXmlPathMap[$vatClass])) { $groupId = (int)$this->scopeConfig->getValue( $vatClassToGroupXmlPathMap[$vatClass], ScopeInterface::SCOPE_STORE, $store ); } return $groupId; } public function checkVatNumber($countryCode, $vatNumber, $requesterCountryCode = '', $requesterVatNumber = '') { $gatewayResponse = new DataObject([ 'is_valid' => false, 'request_date' => '', 'request_identifier' => '', 'request_success' => false, 'request_message' => __('Error during VAT Number verification.'), ]); if (!extension_loaded('soap')) { $this->logger->critical(new LocalizedException(__('PHP SOAP extension is required.'))); return $gatewayResponse; } if (!$this->canCheckVatNumber($countryCode, $vatNumber, $requesterCountryCode, $requesterVatNumber)) { return $gatewayResponse; } try { $soapClient = $this->createVatNumberValidationSoapClient(); $requestParams = []; $requestParams['countryCode'] = $countryCode; $requestParams['vatNumber'] = str_replace([' ', '-'], ['', ''], $vatNumber); $requestParams['requesterCountryCode'] = $requesterCountryCode; $requestParams['requesterVatNumber'] = str_replace([' ', '-'], ['', ''], $requesterVatNumber); $result = $soapClient->checkVatApprox($requestParams); $gatewayResponse->setIsValid((bool)$result->valid); $gatewayResponse->setRequestDate((string)$result->requestDate); $gatewayResponse->setRequestIdentifier((string)$result->requestIdentifier); $gatewayResponse->setRequestSuccess(true); if ($gatewayResponse->getIsValid()) { $gatewayResponse->setRequestMessage(__('VAT Number is valid.')); } else { $gatewayResponse->setRequestMessage(__('Please enter a valid VAT number.')); } } catch (\Exception $exception) { $gatewayResponse->setIsValid(false); $gatewayResponse->setRequestDate(''); $gatewayResponse->setRequestIdentifier(''); } return $gatewayResponse; } protected function createVatNumberValidationSoapClient($trace = false) { return new \SoapClient(self::VAT_VALIDATION_WSDL_URL, ['trace' => $trace]); } public function canCheckVatNumber($countryCode, $vatNumber, $requesterCountryCode, $requesterVatNumber) { return !(!is_string($countryCode) || !is_string($vatNumber) || !is_string($requesterCountryCode) || !is_string($requesterVatNumber) || empty($countryCode) || !$this->isCountryInEU($countryCode) || empty($vatNumber) || empty($requesterCountryCode) && !empty($requesterVatNumber) || !empty($requesterCountryCode) && empty($requesterVatNumber) || !empty($requesterCountryCode) && !$this->isCountryInEU($requesterCountryCode) ); } public function getCustomerVatClass($customerCountryCode, $vatValidationResult, $store = null) { $vatClass = null; $isVatNumberValid = $vatValidationResult->getIsValid(); if (is_string($customerCountryCode) && !empty($customerCountryCode) && $customerCountryCode === $this->getMerchantCountryCode($store) && $isVatNumberValid ) { $vatClass = self::VAT_CLASS_DOMESTIC; } elseif ($isVatNumberValid) { $vatClass = self::VAT_CLASS_INTRA_UNION; } else { $vatClass = self::VAT_CLASS_INVALID; } if (!$vatValidationResult->getRequestSuccess()) { $vatClass = self::VAT_CLASS_ERROR; } return $vatClass; } public function isCountryInEU($countryCode, $storeId = null) { $euCountries = explode( ',', $this->scopeConfig->getValue(self::XML_PATH_EU_COUNTRIES_LIST, ScopeInterface::SCOPE_STORE, $storeId) ); return in_array($countryCode, $euCountries); } } 